package dev.dwij.chat.common.model;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

import java.util.Objects;

/**
 * The one message shape that travels end to end: WebSocket frame -> Kafka -> Cosmos DB -> cache -> fan-out.
 *
 * <p>messageId is generated by the client and is the idempotency key for the whole pipeline, so a retry
 * after a flaky connection never produces a second row. serverSeq is assigned once, by message-service,
 * and is what everything downstream orders by. Client clocks are not trusted for ordering.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public class ChatMessage {

    private String messageId;
    private String conversationId;
    private String senderId;
    private MessageType type = MessageType.TEXT;
    private String body;
    /** Client clock, kept for display only. */
    private long sentAt;
    /** Monotonic per conversation, assigned server-side. Zero until message-service has seen it. */
    private long serverSeq;
    /** Server clock at the moment of the durable write. */
    private long storedAt;

    public ChatMessage() {
    }

    public ChatMessage(String messageId, String conversationId, String senderId,
                       MessageType type, String body, long sentAt) {
        this.messageId = messageId;
        this.conversationId = conversationId;
        this.senderId = senderId;
        this.type = type == null ? MessageType.TEXT : type;
        this.body = body;
        this.sentAt = sentAt;
    }

    public String getMessageId() {
        return messageId;
    }

    public void setMessageId(String messageId) {
        this.messageId = messageId;
    }

    public String getConversationId() {
        return conversationId;
    }

    public void setConversationId(String conversationId) {
        this.conversationId = conversationId;
    }

    public String getSenderId() {
        return senderId;
    }

    public void setSenderId(String senderId) {
        this.senderId = senderId;
    }

    public MessageType getType() {
        return type;
    }

    public void setType(MessageType type) {
        this.type = type;
    }

    public String getBody() {
        return body;
    }

    public void setBody(String body) {
        this.body = body;
    }

    public long getSentAt() {
        return sentAt;
    }

    public void setSentAt(long sentAt) {
        this.sentAt = sentAt;
    }

    public long getServerSeq() {
        return serverSeq;
    }

    public void setServerSeq(long serverSeq) {
        this.serverSeq = serverSeq;
    }

    public long getStoredAt() {
        return storedAt;
    }

    public void setStoredAt(long storedAt) {
        this.storedAt = storedAt;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof ChatMessage other)) {
            return false;
        }
        return Objects.equals(messageId, other.messageId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(messageId);
    }

    @Override
    public String toString() {
        return "ChatMessage[" + messageId + " conv=" + conversationId + " seq=" + serverSeq + "]";
    }
}
